contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // This test invokes newEmergencyOracle twice: once directly (msg.sender == tx.origin == this contract)
    // and once via a forwarding contract deployed by this test caller (so msg.sender != tx.origin).
    // We observe whether the call succeeds by checking that NewEmergencyOracle event caused the creation
    // of a nonzero oracle address via reading nothing beyond c's public surface — instead we rely on
    // the fact that the call either reverts or not. We capture revert booleans.

    // A minimal forwarder contract used to call c.newEmergencyOracle from another contract.
    contract Forwarder {
        function forwardNew(C target, string calldata description) external returns (bool) {
            // forward the call and return whether it succeeded
            (bool ok, ) = address(target).call(abi.encodeWithSignature("newEmergencyOracle(string)", description));
            return ok;
        }
    }

    // The single public test function. Parameters:
    // - jojo: address that should be set as jojoTeam in the target C instance prior to test (we do not set it here)
    // - desc: description passed to newEmergencyOracle
    // Note: we only use public/external calls on c and very simple boolean observations.
    function runTest(address jojo, string calldata desc) external {
        // Call 1: direct call from this contract (so tx.origin == msg.sender == original caller)
        bool directSucceeded;
        {
            // attempt call and capture success
            (bool ok, ) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", desc));
            directSucceeded = ok;
        }

        // Call 2: forwarded call from another contract (so tx.origin stays the external caller, but msg.sender becomes Forwarder)
        bool forwardedSucceeded;
        {
            Forwarder f = new Forwarder();
            forwardedSucceeded = f.forwardNew(c, desc);
        }

        // The distinguishing rule to assert: when the external caller (tx.origin) is jojo,
        // a forwarded call (msg.sender != tx.origin) should not succeed while a direct call from this contract can behave differently.
        // Concretely: if the forwarded call succeeded while the direct call failed, that indicates modifier uses tx.origin (mutant).
        // We assert that does NOT happen on the original: forwardedSucceeded implies directSucceeded.
        assert(!forwardedSucceeded || directSucceeded);
    }

    // Allow receiving ETH if needed by environments
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // precondition: caller is not the direct jojoTeam (so only direct calls by jojoTeam would succeed on P)
        require(caller != address(0));
        // Simulate a forwarded call by using a helper contract is not allowed here — instead we encode the distinction via the address parameter.
        // We only invoke newEmergencyOracle directly; on the original contract it should revert unless msg.sender == jojoTeam.
        bool reverted;
        try c.newEmergencyOracle("desc") { reverted = false; } catch { reverted = true; }
        // Rule: if the tx sender (msg.sender in this test) is not equal to the jojoTeam address passed as `caller`, then creation must revert on the original contract.
        // Since we cannot read jojoTeam from c, express the rule using the `caller` parameter: when caller != msg.sender, the call must revert.
        assert((caller == msg.sender) || reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    // single public function performing the minimal interactions and final assertion
    function run(address caller) public {
        // precondition: caller is not address(0)
        require(caller != address(0));

        // We cannot change msg.sender here, but we can observe whether calling newEmergencyOracle
        // from THIS contract would succeed (i.e., not revert) depending on how onlyJojoTeam is defined
        // We use a low-level call to detect revert boolean when calling c.newEmergencyOracle

        bytes memory payload = abi.encodeWithSignature("newEmergencyOracle(string)", string("desc"));
        // attempt call from this contract
        (bool successFromThis, ) = address(c).call(payload);

        // Also attempt to detect behaviour when the jojoTeam equals this contract by reading jojoTeam getter
        // Note: jojoTeam is public in C, so it has an auto getter
        address jt = c.jojoTeam();

        // If jt == address(this) then under the original contract onlyJojoTeam allows address(this) to call
        // so successFromThis should be true. Under the mutant it would be inverted and the call would revert.
        // Our assertion captures that relation: successFromThis == (jt == address(this))
        assert(successFromThis == (jt == address(this)));
    }

    // receive and fallback are allowed optionally
    receive() external payable {}
    fallback() external payable {}
}

