    function run(address caller) public payable {
        require(true);
        bool reverted;
        // call newEmergencyOracle from this contract; the behavior depends on whether this contract's address equals c.jojoTeam()
        try c.newEmergencyOracle("desc") { reverted = false; } catch { reverted = true; }
        // General rule: the call should revert iff this contract is not the jojoTeam address
        address team = c.jojoTeam();
        assert(reverted == (address(this) != team));
    }
    receive() external payable {}
